/**
 * A review created at revision 1 and edited at revision 2, then advanced by a Luna tick to revision 3 (no receipt), with a capture,
 * retained filenames, an analysis in flight and a suggestion: everything a tombstone must leave out.
 */
function discardableReview() {
    const { doc } = reviewDoc(), at = new Date(1_000), actor = subject(1);
    const created = { operationId: '00000009-0000-4000-a000-0000000000f1', kind: 'create' as const, revision: 1, actorId: actor, hash: 'a'.repeat(64), at,
        selection: { generation: 0, acceptedIds: [], rejectedIds: [] } };
    doc.receipts = [created, { operationId: '00000009-0000-4000-a000-0000000000f2', kind: 'edit', revision: 2, actorId: actor, hash: 'b'.repeat(64), at }];
    doc.catalogSource!.tracks.forEach((track, index) => { track.originalFileName = `synthetic-file-${index}.flac`; });
    doc.catalogCapture = { capturedAt: at, album: { credits: [], artistsComplete: true, label: 'none', expectedTracklist: null }, members: [] };
    doc.analysis = { ...doc.analysis, state: 'cancelled', generation: 1, chunks: [{ index: 0, state: 'inflight' }] } as unknown as AdminImportDocument['analysis'];
    doc.suggestions = [{ id: 'synthetic-suggestion', field: 'title' }] as unknown as AdminImportDocument['suggestions'];
    return doc;
}
const refused = (code: string) => (error: unknown) => error instanceof AdminImportError && error.status === 409 && error.code === code;
const discardBody = (expectedRevision: number, operationId = '00000009-0000-4000-a000-0000000000f9') => ({ operationId, expectedRevision });

test('a discarded review keeps only its ID, Album ID, creator, discarder, times and its create and discard receipts', () => {
    const doc = discardableReview(), at = new Date(2_000);
    const receipt: CatalogReviewTombstoneReceipt = { operationId: '00000009-0000-4000-a000-0000000000f9', kind: 'discard', revision: 4, actorId: subject(5), hash: 'c'.repeat(64), at };
    const tombstone = catalogReviewTombstone(doc, receipt);
    assert.deepEqual(Object.keys(tombstone).sort(), ['_id', 'actorId', 'albumId', 'createdAt', 'discardedAt', 'discardedBy', 'purpose', 'receipts', 'revision', 'updatedAt']);
    assert.deepEqual({ ...tombstone, receipts: undefined }, { _id: doc._id, purpose: 'catalogReviewDiscarded', actorId: subject(1), createdAt: doc.createdAt, updatedAt: at, revision: 4,
        albumId: subject(2), discardedAt: at, discardedBy: subject(5), receipts: undefined });
    assert.deepEqual(tombstone.receipts.map(value => value.kind), ['create', 'discard']);
    // The create receipt is copied as stored, without its selection; the edit receipt is gone.
    assert.deepEqual(tombstone.receipts[0], { operationId: '00000009-0000-4000-a000-0000000000f1', kind: 'create', revision: 1, actorId: subject(1), hash: 'a'.repeat(64), at: new Date(1_000) });
    assert.equal(tombstone.receipts[1], receipt);
    const json = JSON.stringify(tombstone);
    for (const kept of ['Synthetic Album', '"One"', '"Two"', 'synthetic-file-0.flac', 'Synthetic A', 'Synthetic Label', 'synthetic-suggestion', '"draft"', '"catalogCapture"', '"catalogSource"',
        '"manifest"', '"analysis"', '"suggestions"', '"selection"', '"edit"', 'inflight']) assert.equal(json.includes(kept), false, kept);
    // A review without a create receipt keeps only its discard receipt.
    doc.receipts = []; assert.deepEqual(catalogReviewTombstone(doc, receipt).receipts, [receipt]);
});

test('discard refusals come in order: applied whatever the revision, an operation ID any receipt used, a newer format, a revision before the last receipt or after the current one, then Luna queued or running', () => {
    const used = '00000009-0000-4000-a000-0000000000f2';
    // Every later refusal is present at once, so each assertion shows the earlier check wins.
    const everything = () => { const doc = discardableReview(); doc.draftVersion = 4; doc.analysis.state = 'running'; return doc; };
    const applied = everything(); applied.catalogApplied = { operationId: used, at: new Date(0).toISOString(), fields: [] };
    for (const revision of [1, 2, 3, 9]) assert.throws(() => assertCatalogReviewDiscardable(applied, discardBody(revision, used)), refused('ADMIN_CATALOG_REVIEW_APPLIED'), String(revision));
    for (const where of ['receipts', 'recoveryReceipts', 'automaticReceipts'] as const) {
        const doc = everything(), other = '00000009-0000-4000-a000-0000000000f7';
        if (where !== 'receipts') doc[where] = [{ ...doc.receipts[1], operationId: other }];
        assert.throws(() => assertCatalogReviewDiscardable(doc, discardBody(1, where === 'receipts' ? used : other)), refused('ADMIN_IMPORT_OPERATION_CONFLICT'), where);
    }
    assert.throws(() => assertCatalogReviewDiscardable(everything(), discardBody(1)), refused('ADMIN_IMPORT_RELOAD_REQUIRED'));
    const current = discardableReview(); current.analysis.state = 'queued';
    for (const revision of [1, 4]) assert.throws(() => assertCatalogReviewDiscardable(current, discardBody(revision)), refused('ADMIN_IMPORT_REVISION_CONFLICT'), String(revision));
    for (const state of ['queued', 'running'] as const) {
        const doc = discardableReview(); doc.analysis.state = state;
        assert.throws(() => assertCatalogReviewDiscardable(doc, discardBody(3)), refused('ADMIN_IMPORT_ANALYSIS_ACTIVE'), state);
    }
    // Admitted: the last receipt's revision and a Luna tick past it, a stopped call still in flight, any analysis state that is not
    // active, a format-3 review, and a review at its receipt limit (a discard is never counted against it).
    for (const revision of [2, 3]) assert.doesNotThrow(() => assertCatalogReviewDiscardable(discardableReview(), discardBody(revision)));
    for (const state of ['idle', 'complete', 'needsAttention', 'cancelled'] as const) {
        const doc = discardableReview(); doc.analysis.state = state; assert.doesNotThrow(() => assertCatalogReviewDiscardable(doc, discardBody(3)), state);
    }
    const format3 = discardableReview(); format3.draftVersion = 3; assert.doesNotThrow(() => assertCatalogReviewDiscardable(format3, discardBody(3)));
    const full = discardableReview();
    full.receipts = Array.from({ length: 256 }, (_, index) => ({ ...full.receipts[1], operationId: randomUUID(), revision: index + 1 })); full.revision = 256;
    assert.doesNotThrow(() => assertCatalogReviewDiscardable(full, discardBody(256)));
});

test('a discard body takes only an operation ID and expected revision, and a malformed review ID is not found, before any database access', async () => {
    const id = '0000000000000000000000e1', operationId = '00000009-0000-4000-a000-0000000000f9';
    const invalid = (error: unknown) => error instanceof AdminImportError && error.status === 400 && error.code === 'ADMIN_IMPORT_INVALID_INPUT';
    for (const body of [{ operationId, expectedRevision: 1, extra: true }, { operationId: 'not-a-uuid', expectedRevision: 1 }, { operationId, expectedRevision: 0 },
        { operationId, expectedRevision: 1.5 }, { operationId }, { expectedRevision: 1 }, null, [], 'discard']) await assert.rejects(discardCatalogReview(subject(1), id, body), invalid, JSON.stringify(body));
    // The body is checked first, so a malformed ID with a malformed body is still invalid input.
    await assert.rejects(discardCatalogReview(subject(1), 'bad', { operationId }), invalid);
    for (const bad of ['bad', '', `${id}0`, id.toUpperCase().replace('E', 'G')]) await assert.rejects(discardCatalogReview(subject(1), bad, { operationId, expectedRevision: 1 }),
        (error: unknown) => error instanceof AdminImportError && error.status === 404 && error.code === 'ADMIN_CATALOG_REVIEW_NOT_FOUND', bad);
});

test('the discarded-review probe is false for a malformed ID and never throws without a database', async () => {
    // A failed probe keeps the route's own 404: the routes report a review as discarded only when its tombstone was read.
    for (const id of ['bad', '', '0'.repeat(24)]) assert.equal(await catalogReviewDiscarded(id), false, id);
});
